404 72 https://unpkg.com/three@0.160.0/examples/textures/planets/earth_atmos_2048.jpg
200 512606 https://cdn.jsdelivr.net/gh/mrdoob/three.js@r160/examples/textures/planets/earth_atmos_2048.jpg
200 734910 https://cdn.jsdelivr.net/gh/mrdoob/three.js@r160/examples/textures/planets/earth_lights_2048.png
200 223421 https://cdn.jsdelivr.net/gh/mrdoob/three.js@r160/examples/textures/planets/earth_specular_2048.jpg
200 336774 https://cdn.jsdelivr.net/gh/mrdoob/three.js@r160/examples/textures/planets/earth_normal_2048.jpg
200 260222 https://cdn.jsdelivr.net/gh/mrdoob/three.js@r160/examples/textures/planets/earth_clouds_1024.png
function makeStars(count, spread) {
  const pos = new Float32Array(count * 3);
  const col = new Float32Array(count * 3);
  const c = new THREE.Color();
  for (let i = 0; i < count; i++) {
    // uniform points on a shell
    const u = Math.random() * 2 - 1;
    const theta = Math.random() * Math.PI * 2;
    const r = spread * (0.75 + Math.random() * 0.25);
    const s = Math.sqrt(1 - u * u);
    pos[i * 3]     = r * s * Math.cos(theta);
    pos[i * 3 + 1] = r * u;
    pos[i * 3 + 2] = r * s * Math.sin(theta);

    const t = Math.random();
    c.setHSL(t < 0.8 ? 0.58 : 0.08, 0.35, 0.55 + Math.random() * 0.45);
    col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  return g;
}

const stars = new THREE.Points(
  makeStars(7000, 400),
  new THREE.PointsMaterial({
    size: 1.1,
    sizeAttenuation: false,
    vertexColors: true,
    transparent: true,
    opacity: 0.9,
    depthWrite: false
  })
);
scene.add(stars);

const brightStars = new THREE.Points(
  makeStars(220, 400),
  new THREE.PointsMaterial({
    size: 2.6,
    sizeAttenuation: false,
    vertexColors: true,
    transparent: true,
    opacity: 0.85,
    depthWrite: false
  })
);
scene.add(brightStars);

// ------------------------------------------------------------------ animation
const clock = new THREE.Clock();

function tick() {
  const dt = clock.getDelta();

  earth.rotation.y  += dt * 0.055;
  clouds.rotation.y += dt * 0.072;   // clouds drift a touch faster
  stars.rotation.y  += dt * 0.002;

  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(tick);
}
tick();

addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

const hint = document.getElementById('hint');
setTimeout(() => { hint.style.opacity = '0'; }, 5000);
</script>
</body>
</html>

